public sealed class MqHandlerDispatchTests
{
    [Fact]
    public void EveryHandledEventHasADispatchMethod()
    {
        var expected = new[]
        {
            "HandleBookAddedAsync",
            "HandleBookStatusChangedAsync",
            "HandleOverdueBooksProcessedAsync",
        };
        foreach (var handlerName in expected)
        {
            var method = typeof(MqConsumerService).GetMethod(
                handlerName,
                BindingFlags.Instance | BindingFlags.NonPublic
            );
            Assert.True(method is not null, $"Missing dispatch handler method: {handlerName}");
        }
    }

    [Fact]
    public void HandleBookAddedAsync_HasExpectedPayloadParameter()
    {
        var method = typeof(MqConsumerService).GetMethod(
            "HandleBookAddedAsync",
            BindingFlags.Instance | BindingFlags.NonPublic
        );
        Assert.NotNull(method);
        var parameters = method!.GetParameters();
        Assert.Single(parameters);
        Assert.Equal(typeof(BookAddedPayload), parameters[0].ParameterType);
    }

